    InputStream inputStream = incomingMsg.getContent(InputStream.class);
    Reader inputReader = null;
    if (inputStream == null) {
        inputReader = incomingMsg.getContent(Reader.class);
        if (inputReader == null) {
            return;
        }
    }
    String mimeType = (String) incomingMsg.get(Message.CONTENT_TYPE);
    if (mimeType != null && mimeType.contains("text/html")) {
        String htmlContent = null;
        try {
            htmlContent = IOUtils.toString(inputStream, 500);
        } catch (IOException e) {
            throw new Fault(new org.apache.cxf.common.i18n.Message("UNEXPECTED_HTML_CONTENT_TYPE", LOG, "(none)"));
        }
        throw new Fault(new org.apache.cxf.common.i18n.Message("UNEXPECTED_HTML_CONTENT_TYPE", LOG, (htmlContent == null || htmlContent.length() == 0) ? "(none)" : htmlContent));
    }
    if (mimeType == null) {
        // If the mimeType is absent, possibly an empty body in POST/PUT/DELETE requests, check headers
        Map<String, List<String>> headers = CastUtils.cast((Map<?, ?>) incomingMsg.get(Message.PROTOCOL_HEADERS));
        if (headers != null) {
            List<String> contentLength = HttpHeaderHelper.getHeader(headers, HttpHeaderHelper.CONTENT_LENGTH);
            List<String> transferEncoding = HttpHeaderHelper.getHeader(headers, HttpHeaderHelper.CONTENT_TRANSFER_ENCODING);
            if ((StringUtils.isEmpty(contentLength) || "0".equals(contentLength.get(0))) && StringUtils.isEmpty(transferEncoding)) {
                return;
            }
        }
    }
    String charset = (String) incomingMsg.get(Message.ENCODING);
    XMLStreamReader xmlReader;
    try {
        XMLInputFactory xmlFactory = getXMLInputFactory(incomingMsg);
        if (xmlFactory == null) {
            if (inputReader != null) {
                xmlReader = StaxUtils.createXMLStreamReader(inputReader);
            } else {
                xmlReader = StaxUtils.createXMLStreamReader(inputStream, charset);
            }
        } else {
            synchronized (xmlFactory) {
                if (inputReader != null) {
                    xmlReader = xmlFactory.createXMLStreamReader(inputReader);
                } else {
                    xmlReader = xmlFactory.createXMLStreamReader(inputStream, charset);
                }
            }
        }
        xmlReader = configureXMLReaderRestrictions(xmlReader, incomingMsg);
    } catch (XMLStreamException e) {
        throw new Fault(new org.apache.cxf.common.i18n.Message("ERROR_CREATING_XML_STREAM", LOG, charset), e);
    }
    incomingMsg.setContent(XMLStreamReader.class, xmlReader);
    incomingMsg.getInterceptorChain().add(StaxInEndingInterceptor.INSTANCE);
}

