    final byte[] hashedKey;
    final byte[] authServerKey;
    final int pwdIterationCount;
    final SaslException authException;
    if (account == null) {
        // Avoid revealing the non-existence of the user by returning random data, making it look like a generic authentication error.
        encryptionSalt = generateRandomSalt();
        hashedKey = null;
        authServerKey = null;
        pwdIterationCount = -1;
        authException = new SaslException("Authentication Failed");
    } else {
