        final String[] credentialsParts = account.getPassword().split(",");
        encryptionSalt = Strings.decodeBase64(credentialsParts[PasswordField.SALT.ordinal()]);
        hashedKey = Strings.decodeBase64(credentialsParts[PasswordField.STORED_KEY.ordinal()]);
        authServerKey = Strings.decodeBase64(credentialsParts[PasswordField.SERVER_KEY.ordinal()]);
        pwdIterationCount = Integer.parseInt(credentialsParts[PasswordField.ITERATION_COUNT.ordinal()]);
        authException = null;
    }
    return new SaltAndPasswordKeys() {

        @Override
        public byte[] getSalt() {
            return encryptionSalt;
        }

        @Override
        public byte[] getStoredKey() throws SaslException {
            if (hashedKey == null) {
                throw authException;
            }
            return hashedKey;
        }

        @Override
        public byte[] getServerKey() throws SaslException {
            if (authServerKey == null) {
                throw authException;
            }
            return authServerKey;
