 * If path adjustment results in an invalid path, returns null
 *
 * @param inputPath The path to adjust
 * @return The adjusted path or null if invalid
 */
protected String adjustPath(String inputPath) {
    if (inputPath == null) {
        return null;
    }
    String adjustedPath = inputPath;
    // Handle paths starting with double-slash
    if (adjustedPath.startsWith("//")) {
        adjustedPath = adjustedPath.replace("//", "/");
    }
    // Standardize slashes to forward slashes
    if (adjustedPath.contains("\\")) {
        adjustedPath = adjustedPath.replace('\\', '/');
    }
    // Eliminate "/../" segments
    while (true) {
        int idx = adjustedPath.indexOf("/../");
        if (idx < 0) {
            break;
        }
        if (idx == 0) {
            // This results in an invalid path
            return null;
        }
        int precedingSlashIdx = adjustedPath.lastIndexOf('/', idx - 1);
        adjustedPath = adjustedPath.substring(0, precedingSlashIdx) + adjustedPath.substring(idx + 3);
    }
    // Resolve "./" segments
    adjustedPath = evaluateNormalizedPathWithSinglePoint(adjustedPath);
    // Ensure the path starts with a "/"
    if (!adjustedPath.startsWith("/")) {
        adjustedPath = "/" + adjustedPath;
    }
    // Return the adjusted path
    return adjustedPath;
}

